    try {
        var provider = smProviderModule.createSmProvider({
            scm: { provider: 'github' },
            repository: repoInfo
        });
        var st = provider.prStatus(prNumber);
        return !!st && st.checkConclusion === 'red';
    } catch (e) {
        console.warn('  ⚠️  red-rollup probe failed: ' + (e.message || e));
        return false;
    }
}

