  // `ci-workflow` input) > 'quality.yml'.
  function dispatchCiWorkflow(branchName) {
      var ciWorkflow = rule.ciWorkflow ||
          ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml';
      if (DRY) {
          // Live bug (fa 2026-09-27): a DRY SM tick really dispatched
